steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        teams(filter: {name: {eq: \"Web\"}}) {
          nodes {
            id
            name
            issues(filter: {
              state: {name: {eq: \"Done\"}}
              assignee: {name: {eq: \"Priya Nair\"}}
            }) {
              nodes {
                id
                title
                description
                priority
                completedAt
                assignee {
                  name
                }
                state {
                  name
                }
              }
            }
          }
        }
      }
    '
  }'
